int licznik = 0;
int liczba = 0;

void Znak(int iNumer) {
  // Sterowanie dodatkowym pinem (np. kropka)
  digitalWrite(8, ((iNumer == 0) || (iNumer == 1) || (iNumer == 7)) ? HIGH : LOW);

  // Wzorce bitowe dla portu D (piny 0-7)
  switch (iNumer) {
    case 0: PORTD = 0b00000000; break;
    case 1: PORTD = 0b11100100; break;
    case 2: PORTD = 0b01001001; break;
    case 3: PORTD = 0b01000011; break;
    case 4: PORTD = 0b00100110; break;
    case 5: PORTD = 0b00010010; break;
    case 6: PORTD = 0b00010000; break;
    case 7: PORTD = 0b11000111; break;
    case 8: PORTD = 0b00000000; break;
    case 9: PORTD = 0b11000010; break;
    default: PORTD = 0b11011000; break;
  }
}

void setup() {
  for (int i = 2; i < 9; i++) {
    pinMode(i, OUTPUT);
  }
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);
}

void loop() {
  // Multipleksowanie wyświetlacza (odświeżanie cyfr)
  digitalWrite(11, LOW);
  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);

  digitalWrite(10, LOW);
  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);

  // Zwiększanie liczby co określony czas (ok. 400 ms)
  delay(400);
  if (licznik++ > 100) {
    liczba++;
    if (liczba > 99) {
      liczba = 0; // Powrót do 0 po osiągnięciu 99
    }
    licznik = 0;
  }
}
